<?php
defined('ABSPATH') || exit;

final class MDA_Cheque_Admin {
 public static function init(): void {
  add_action('admin_menu',array(__CLASS__,'menu'));
  add_action('admin_post_mda_register_cheque',array(__CLASS__,'register'));
  add_action('admin_post_mda_transition_cheque',array(__CLASS__,'transition'));
 }
 public static function menu(): void {add_submenu_page('mda-accounting','دفتر چک','دفتر چک',MDA_Capabilities::MANAGE,'mda-cheques',array(__CLASS__,'render'));}
 private static function guard(): void {if(!current_user_can(MDA_Capabilities::MANAGE))wp_die(esc_html__('شما اجازه دسترسی به این بخش را ندارید.','malidev-accounting'));}
 public static function register(): void {
  self::guard();check_admin_referer('mda_register_cheque');
  try{$in=array('cheque_type'=>sanitize_key(wp_unslash($_POST['cheque_type']??'')),'party_id'=>absint($_POST['party_id']??0),'bank_account_id'=>absint($_POST['bank_account_id']??0),'cheque_number'=>sanitize_text_field(wp_unslash($_POST['cheque_number']??'')),'amount_minor'=>filter_var((string)($_POST['amount_minor']??''),FILTER_VALIDATE_INT),'currency_code'=>sanitize_text_field(wp_unslash($_POST['currency_code']??'IRR')),'issue_date'=>sanitize_text_field(wp_unslash($_POST['issue_date']??'')),'due_date'=>sanitize_text_field(wp_unslash($_POST['due_date']??'')),'description'=>sanitize_text_field(wp_unslash($_POST['description']??'')),'request_key'=>sanitize_text_field(wp_unslash($_POST['request_key']??'')));if(false===$in['amount_minor'])throw new InvalidArgumentException('مبلغ معتبر نیست.');$r=MDA_Cheque_Service::register($in);$url=add_query_arg(array('page'=>'mda-cheques','mda_notice'=>$r['duplicate']?'duplicate':'registered'),admin_url('admin.php'));}
  catch(Throwable $e){$url=add_query_arg(array('page'=>'mda-cheques','mda_error'=>rawurlencode($e->getMessage())),admin_url('admin.php'));}wp_safe_redirect($url);exit;
 }
 public static function transition(): void {
  self::guard();$id=absint($_POST['cheque_id']??0);check_admin_referer('mda_transition_cheque_'.$id);
  try{$action=sanitize_key(wp_unslash($_POST['transition']??''));$date=sanitize_text_field(wp_unslash($_POST['event_date']??''));$key=sanitize_text_field(wp_unslash($_POST['request_key']??''));$note=sanitize_text_field(wp_unslash($_POST['note']??''));MDA_Cheque_Service::transition($id,$action,$date,$key,$note);$url=add_query_arg(array('page'=>'mda-cheques','mda_notice'=>'transitioned'),admin_url('admin.php'));}
  catch(Throwable $e){$url=add_query_arg(array('page'=>'mda-cheques','mda_error'=>rawurlencode($e->getMessage())),admin_url('admin.php'));}wp_safe_redirect($url);exit;
 }
 private static function notices(): void {$messages=array('registered'=>'چک با موفقیت در SQLite ثبت شد.','duplicate'=>'این چک قبلاً ثبت شده است.','transitioned'=>'وضعیت چک و سند حسابداری مربوط ثبت شد.');$key=sanitize_key(wp_unslash($_GET['mda_notice']??''));if(isset($messages[$key]))echo '<div class="notice notice-success"><p>'.esc_html($messages[$key]).'</p></div>';if(!empty($_GET['mda_error']))echo '<div class="notice notice-error"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['mda_error']))).'</p></div>';}
 public static function render(): void {
  self::guard();if(!MDA_Database::is_available()){echo '<div class="wrap"><div class="notice notice-error"><p>PDO_SQLite فعال نیست.</p></div></div>';return;}
  $parties=MDA_Party_Service::search('',200);$banks=MDA_Bank_Reconciliation_Service::bank_accounts();$rows=MDA_Cheque_Service::list();$due=MDA_Cheque_Service::due(7);$type=sanitize_key(wp_unslash($_GET['type']??''));$fmt=static function($n):string{return number_format((int)$n,0,'.',',');};
  echo '<div class="wrap" dir="rtl"><h1>دفتر چک</h1>';self::notices();
  echo '<p>ثبت و پیگیری چک‌های دریافتی و صادره؛ تغییر وضعیت‌ها با رویداد غیرقابل‌حذف و سند حسابداری در SQLite ثبت می‌شود.</p>';
  echo '<div class="mda-card" style="margin:16px 0;padding:18px"><h2>ثبت چک جدید</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="mda_register_cheque">';wp_nonce_field('mda_register_cheque');echo '<input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'"><div class="mda-grid">';
  echo '<label>نوع چک<select name="cheque_type" required><option value="received">دریافتی از مشتری</option><option value="issued">صادره برای تأمین‌کننده</option></select></label>';
  echo '<label>طرف‌حساب<select name="party_id" required><option value="">انتخاب طرف‌حساب</option>';foreach($parties as $p)echo '<option value="'.(int)$p['id'].'">'.esc_html($p['party_code'].' — '.$p['display_name']).'</option>';echo '</select><small>برای چک دریافتی مشتری و برای چک صادره تأمین‌کننده انتخاب شود.</small></label>';
  echo '<label>حساب بانکی<select name="bank_account_id" required><option value="">انتخاب بانک</option>';foreach($banks as $b)echo '<option value="'.(int)$b['id'].'">'.esc_html($b['account_code'].' — '.$b['account_name']).'</option>';echo '</select></label>';
  echo '<label>شماره چک<input name="cheque_number" maxlength="80" required></label><label>مبلغ<input type="number" name="amount_minor" min="1" required></label><label>واحد پول<select name="currency_code"><option value="IRR">ریال</option><option value="IRT">تومان</option></select></label><label>تاریخ صدور<input type="date" name="issue_date" value="'.esc_attr(current_time('Y-m-d')).'" required></label><label>تاریخ سررسید<input type="date" name="due_date" required></label><label>شرح<input name="description" maxlength="500"></label></div><p><button class="button button-primary">ثبت چک</button></p></form></div>';
  echo '<h2>چک‌های نزدیک سررسید (۷ روز آینده و معوق)</h2><table class="widefat striped"><thead><tr><th>شماره</th><th>نوع</th><th>طرف‌حساب</th><th>سررسید</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>';foreach($due as $c)echo '<tr><td>'.esc_html($c['cheque_number']).'</td><td>'.($c['cheque_type']==='received'?'دریافتی':'صادره').'</td><td>'.esc_html($c['party_name']).'</td><td>'.esc_html($c['due_date']).'</td><td>'.esc_html($fmt($c['amount_minor']).' '.$c['currency_code']).'</td><td>'.esc_html($c['status']).'</td></tr>';if(!$due)echo '<tr><td colspan="6">چک سررسیدشده‌ای در این بازه وجود ندارد.</td></tr>';echo '</tbody></table>';
  echo '<h2 class="mda-section-title">همه چک‌ها</h2><p><a class="button" href="'.esc_url(admin_url('admin.php?page=mda-cheques')).'">همه</a> <a class="button" href="'.esc_url(admin_url('admin.php?page=mda-cheques&type=received')).'">دریافتی</a> <a class="button" href="'.esc_url(admin_url('admin.php?page=mda-cheques&type=issued')).'">صادره</a></p>';
  $rows=MDA_Cheque_Service::list(array('type'=>$type));echo '<table class="widefat striped"><thead><tr><th>شماره چک</th><th>نوع</th><th>طرف‌حساب</th><th>بانک</th><th>تاریخ سررسید</th><th>مبلغ</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>';
  foreach($rows as $c){$status=$c['status']?:'registered';echo '<tr><td>'.esc_html($c['cheque_number']).'</td><td>'.($c['cheque_type']==='received'?'دریافتی':'صادره').'</td><td>'.esc_html($c['party_name']).'</td><td>'.esc_html($c['bank_code'].' — '.$c['bank_name']).'</td><td>'.esc_html($c['due_date']).'</td><td>'.esc_html($fmt($c['amount_minor']).' '.$c['currency_code']).'</td><td>'.esc_html(array('registered'=>'ثبت‌شده','deposited'=>'واگذار‌شده','cleared'=>'وصول‌شده','bounced'=>'برگشتی','voided'=>'باطل‌شده')[$status]??$status).'</td><td>';
   if(in_array($status,array('registered','deposited'),true)){foreach(array('deposit'=>'واگذاری به بانک','clear'=>'وصول','bounce'=>'برگشت','void'=>'ابطال') as $action=>$label){if($action==='deposit'&&($c['cheque_type']!=='received'||$status!=='registered'))continue;if($action==='void'&&$status!=='registered')continue;echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="display:inline-block;margin:2px"><input type="hidden" name="action" value="mda_transition_cheque"><input type="hidden" name="cheque_id" value="'.(int)$c['id'].'"><input type="hidden" name="transition" value="'.esc_attr($action).'"><input type="hidden" name="event_date" value="'.esc_attr(current_time('Y-m-d')).'"><input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'">';wp_nonce_field('mda_transition_cheque_'.(int)$c['id']);echo '<button class="button" onclick="return confirm('.esc_attr(wp_json_encode($label.' برای این چک ثبت شود؟')).')">'.esc_html($label).'</button></form>';}}
   echo '</td></tr>';}
  if(!$rows)echo '<tr><td colspan="8">چکی ثبت نشده است.</td></tr>';echo '</tbody></table></div>';
 }
}
